using Xunit;

namespace Umpk.Protocol.Bedrock.Tests.World;

public sealed class BedrockSubChunkPayloadCodecTests
{
    [Fact]
    public void LiveSporeBlossomSectionDecodesActorsAndRoundTrips()
    {
        byte[] payload = Convert.FromHexString("");

        (BedrockChunkSection section, IReadOnlyList<BedrockBlockActorData> actors) = BedrockChunkPayloadCodecs.DecodeSubChunkPayload(payload);

        Assert.Equal(-1, section.SectionY);
        Assert.Single(section.Layers);
        BedrockBlockActorData actor = Assert.Single(actors);
        Assert.Equal(-42, actor.X);
        Assert.Equal(-11, actor.Y);
        Assert.Equal(29, actor.Z);
        Assert.Equal("SporeBlossom", actor.Identifier);
        Assert.Equal(payload, BedrockChunkPayloadCodecs.EncodeSubChunkPayload(section, actors));
    }

    [Fact]
    public void LiveSporeBlossomSectionVariantDecodesActorsAndRoundTrips()
    {
        byte[] payload = Convert.FromHexString("");

        (BedrockChunkSection section, IReadOnlyList<BedrockBlockActorData> actors) = BedrockChunkPayloadCodecs.DecodeSubChunkPayload(payload);

        Assert.Equal(-1, section.SectionY);
        Assert.Single(section.Layers);
        BedrockBlockActorData actor = Assert.Single(actors);
        Assert.Equal(-22, actor.X);
        Assert.Equal(-4, actor.Y);
        Assert.Equal(-88, actor.Z);
        Assert.Equal("SporeBlossom", actor.Identifier);
        Assert.Equal(payload, BedrockChunkPayloadCodecs.EncodeSubChunkPayload(section, actors));
    }

    [Fact]
    public void SectionWithoutActorsRoundTripsThroughSubChunkPayload()
    {
        var section = new BedrockChunkSection(-4, [new BedrockBlockStorage(0, true, [21], new int[BedrockBlockStorage.CellCount])]);

        (BedrockChunkSection decoded, IReadOnlyList<BedrockBlockActorData> actors) = BedrockChunkPayloadCodecs.DecodeSubChunkPayload(BedrockChunkPayloadCodecs.EncodeSubChunkPayload(section, []));

        Assert.Equal(-4, decoded.SectionY);
        Assert.Empty(actors);
    }

    [Fact]
    public void RejectsTrailingGarbageAfterSection()
    {
        byte[] section = BedrockChunkPayloadCodecs.EncodeSection(new BedrockChunkSection(0, [new BedrockBlockStorage(0, true, [1], new int[BedrockBlockStorage.CellCount])]));
        byte[] trailing = [.. section, 0x7F];

        Assert.Throws<BedrockCodecException>(() => BedrockChunkPayloadCodecs.DecodeSubChunkPayload(trailing));
    }

    [Fact]
    public void RejectsTruncatedActorAfterSection()
    {
        byte[] payload = Convert.FromHexString("");
        byte[] truncated = payload[..^1];

        Assert.Throws<BedrockCodecException>(() => BedrockChunkPayloadCodecs.DecodeSubChunkPayload(truncated));
    }
}
